def e(
    episode_id: str,
    title: str,
    question: str,
    opening: str,
    event_ids: list[str],
    observation_ids: list[str],
    locations: list[str],
    evidence_description: str,
    relation_ids: list[str],
    character_ids: list[str],
    relation_choice: str,
    relation_delta: str,
    profession_character: str,
    profession_action: str,
    clue_kind: str,
    clue_description: str,
    misread: str,
    recheck: str,
    reframe: str,
    cost: str,
    choice_actor: str,
    choice_action: str,
    choice_cost: str,
    state_change: str,
    tail_type: str,
    tail_text: str,
    next_chase: str,
    seed: str,
    pov_names: list[str],
    evidence_ids: list[str],
) -> dict:
    episode_number = int(episode_id[-2:])
    return {
        "episode_id": episode_id,
        "arc_id": f"ARC-{((episode_number - 1) // 6) + 1:02d}",
        "title": title,
        "status": "SEASON-DRAFT",
        "duration_minutes": 45,
        "central_question": question,
        "opening_state": opening,
        "city_evidence": {
            "event_ids": event_ids,
            "observation_ids": observation_ids,
            "object_ids": [],
            "clue_ids": [],
            "location_ids": locations,
            "description": evidence_description,
            "canon_refs": [
                "canon/institutions/05-y0-crisis-causal-chain.md",
                "canon/03-spring-letter-system.md",
                "story/01-causal-mystery-and-pacing-revision-v2.md",
            ],
        },
        "relationship_choice": {
            "relation_ids": relation_ids,
            "character_ids": character_ids,
            "choice": relation_choice,
            "delta": relation_delta,
            "evidence_ids": evidence_ids,
        },
        "profession_action": {
            "character_id": CHARACTER_BY_NAME[profession_character],
            "action": profession_action,
            "capability_ref": CAPABILITY_REF_BY_NAME.get(profession_character, "characters/00-character-index.md"),
        },
        "clue_seed": {"kind": clue_kind, "description": clue_description, "source_ids": event_ids + observation_ids},
        "misread": misread,
        "recheck": recheck,
        "reframe": reframe,
        "irreversible_cost": cost,
        "episode_choice": {
            "actor": CHARACTER_BY_NAME[choice_actor],
            "action": choice_action,
            "cost": choice_cost,
            "state_change": state_change,
        },
        "tail_hook": {"type": tail_type, "text": tail_text},
        "next_chase": next_chase,
        "causal_chain": {"seed": seed, "misread": misread, "recheck": recheck, "reframe": reframe},
        "continuity_refs": [episode_id, *event_ids, *observation_ids, *evidence_ids],
        "pov_ids": [CHARACTER_BY_NAME[name] for name in pov_names],
    }


