FUNCTIONS = ["生活入口", "异常进入", "跨过门槛", "职业验证", "生活承载", "第一闭环", "换生活圈", "关系碰撞", "中点改义", "制度/利益反应", "落到具体人", "关系状态变化", "提出方案", "看见代价", "执行", "真相兑现", "伦理决定", "母集闭环"]
HOOK_TYPES = ["生活异样", "物件", "行动门槛", "证据", "交易", "局部闭环", "换视角", "关系裂口", "重义", "制度反应", "具体代价", "关系状态", "选择", "舍弃", "动作", "真相", "伦理", "片尾"]


def parse_draft_rows() -> list[dict]:
    text = DRAFT_PATH.read_text(encoding="utf-8")
    rows = []
    pattern = re.compile(r"^\|\s*(S1-E\d{2}-M\d{2})\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*(.*?)\s*\|\s*$", re.M)
    for chapter_id, pov_name, function, task in pattern.findall(text):
        rows.append({"chapter_id": chapter_id, "pov_name": pov_name.strip(), "function": function.strip(), "task": task.strip()})
    if len(rows) != 648:
        raise SystemExit(f"expected 648 beat rows, found {len(rows)}")
    return rows


def extract_specific_task(task: str, function: str) -> str:
    if "把“" in task and "”拆成" in task:
        return task.split("把“", 1)[1].split("”拆成", 1)[0].strip()
    if "引入本集关系线：" in task:
        return task.split("引入本集关系线：", 1)[1].split("……", 1)[0].strip()
    if "方案必须通向本集既定选择：" in task:
        return task.split("方案必须通向本集既定选择：", 1)[1].split("……", 1)[0].strip()
    if "落点必须兑现：" in task:
        return task.split("落点必须兑现：", 1)[1].strip().rstrip("。")
    return ""


def chapter_specific(row: dict, episode: dict, index: int) -> str:
    """Turn the draft's coarse beat prompt into a playable, episode-specific action."""
    function = row["function"]
    task_specific = extract_specific_task(row["task"], function)
    if index == 0:
        return episode["opening_state"]
    if index == 1:
        return episode["clue_seed"]["description"]
    if index == 2:
        return f"{row['pov_name']}主动介入：{episode['next_chase']}"
    if index == 3:
        return episode["profession_action"]["action"]
    if index == 4:
        return f"把异常放进日常账单：{episode['city_evidence']['description']}"
    if index == 5:
        return f"先回答局部问题，再把下一层疑问交给{row['pov_name']}：{episode['recheck']}"
    if index in (6, 7):
        return task_specific or episode["relationship_choice"]["choice"]
    if index == 8:
        return episode["reframe"]
    if index == 9:
        return f"规则、资源或名声开始反应：{episode['irreversible_cost']}"
    if index == 10:
        return f"让一个具体人支付账单：{episode['irreversible_cost']}"
    if index == 11:
        return episode["relationship_choice"]["delta"]
    if index == 12:
        return task_specific or episode["episode_choice"]["action"]
    if index == 13:
        return episode["episode_choice"]["cost"]
    if index == 14:
        return episode["episode_choice"]["action"]
    if index == 15:
        return episode["reframe"]
    if index == 16:
        return episode["episode_choice"]["action"]
    return episode["tail_hook"]["text"]


def build_hook_rows(ledger: dict, rows: list[dict]) -> list[dict]:
    episodes = {item["episode_id"]: item for item in ledger["episodes"]}
    by_episode: dict[str, list[dict]] = {}
    for row in rows:
        by_episode.setdefault(row["chapter_id"][:6], []).append(row)
    output = []
    for episode_id in [f"S1-E{i:02d}" for i in range(1, 37)]:
        episode = episodes[episode_id]
        ep_rows = by_episode[episode_id]
        for index, row in enumerate(ep_rows):
            chapter_id = row["chapter_id"]
            specific = chapter_specific(row, episode, index)
            next_row = ep_rows[index + 1] if index + 1 < len(ep_rows) else None
            next_specific = chapter_specific(next_row, episode, index + 1) if next_row else episode["next_chase"]
            pov_id = CHARACTER_BY_NAME.get(row["pov_name"], CHARACTER_BY_NAME["沈蘅"])
            function = row["function"] if row["function"] in FUNCTIONS else "生活承载"
            if not specific:
                if function == "制度/利益反应":
                    specific = f"{row['pov_name']}面对‘{episode['central_question']}’，规则、资源或名声迫使其改变行动。"
                elif function == "落到具体人":
                    specific = f"{row['pov_name']}把异常落到一个具体人的饭、药、工钱、名声或去处上。"
                elif function == "关系状态变化":
                    specific = f"{row['pov_name']}与身边同伴的信任、敬意、亏欠或边界发生可见变化。"
                elif function == "真相兑现":
                    specific = f"{row['pov_name']}用一个物件、职业动作或停顿回收‘{episode['reframe']}’的一部分。"
                elif function == "伦理决定":
                    specific = f"{row['pov_name']}在‘{episode['episode_choice']['action']}’之前明确承担一项可见代价。"
                else:
                    specific = f"{row['pov_name']}继续处理‘{episode['central_question']}’，但本章只推进一小步。"
            if index == 0:
                cold_hook = episode["opening_state"]
            else:
                cold_hook = f"上一章留下的动作没有结束：{ep_rows[index - 1]['pov_name']}的记录、物件或关系余波把问题递给{row['pov_name']}。"
            obstacle = {
                "生活入口": "日常节奏要求先把事情做完，异常只能从一个小动作露出来。",
                "异常进入": "普通解释仍然成立，角色不能凭感觉宣布结论。",
                "跨过门槛": "介入会让角色失去时间、收入、名声或安全。",
                "职业验证": "职业工具能确认一部分，却不能替代其他信道。",
                "生活承载": "宏观问题必须落到一个具体人的生活账单。",
                "第一闭环": "本章只能解决局部问题，答案会把更大问题推近。",
                "换生活圈": "另一阶层的观察会改变原解释，而不是重复它。",
                "关系碰撞": "两个人目标相近但方法不同，任何一句话都会留下关系后果。",
                "中点改义": "已有事实被重新解释，新增信息不能凭空跳出。",
                "制度/利益反应": "规则或资源拥有者会为自己的秩序付出代价，也会制造阻力。",
                "落到具体人": "一个具体人的损失不能被‘大局’抹平。",
                "关系状态变化": "亲近上升的同时，信任、依赖或边界至少一项下降。",
                "提出方案": "方案必须可执行，并直接通向本集已锁定选择。",
                "看见代价": "角色必须看见谁替这个方案支付生活账单。",
                "执行": "动作只能使用前文建立的职业能力、地形与关系权限。",
                "真相兑现": "真相不能撤销已经发生的伤害，只能重新分配责任。",
                "伦理决定": "角色要选择愿意成为什么样的人，而不是选择无代价的正确。",
                "母集闭环": "局部问题收束，但片尾只能打开相邻的下一层追问。",
            }.get(function, "本章必须产生一个可观察的变化。")
            if function == "母集闭环":
                tail_type = episode["tail_hook"]["type"]
                tail_hook = episode["tail_hook"]["text"]
                next_chase = episode["next_chase"]
            else:
                tail_type = HOOK_TYPES[index]
                tail_hook = f"{specific}；下一章必须回应：{next_specific}"
                next_chase = next_specific
            choice_cost = episode["episode_choice"]["cost"] if index >= 12 else f"暂不下最终结论；本章承担的即时代价是：{episode['irreversible_cost']}"
            state_delta = f"{row['pov_name']}完成‘{function}’：知识位置、关系位置或行动权限发生一项改变；本集状态线为：{episode['episode_choice']['state_change']}"
            output.append({
                "chapter_id": chapter_id,
                "episode_id": episode_id,
                "sequence": index + 1,
                "duration_seconds": 150,
                "pov_id": pov_id,
                "pov_name": row["pov_name"],
                "function": function,
                "cold_hook": cold_hook,
                "goal_obstacle": f"目标：推进‘{episode['central_question']}’；阻碍：{obstacle}",
                "evidence_or_relationship_action": specific,
                "choice_cost": choice_cost,
                "tail_hook_type": tail_type,
                "tail_hook": tail_hook,
                "next_chase": next_chase,
                "state_delta": state_delta,
            })
    return output


def main() -> int:
    ledger = json.loads(LEDGER_PATH.read_text(encoding="utf-8"))
    by_id = {item["episode_id"]: item for item in ledger["episodes"]}
    for episode_id, data in EPISODES.items():
        activity_ids = by_id[episode_id].get("activity_ids", [])
        humor_ids = by_id[episode_id].get("humor_ids", [])
        data["activity_ids"] = activity_ids
        data["humor_ids"] = humor_ids
        by_id[episode_id] = data
    ledger["episodes"] = [by_id[f"S1-E{i:02d}"] for i in range(1, 37)]
    for episode in ledger["episodes"]:
        episode["status"] = "SEASON-DRAFT"
    ledger["status"] = "SEASON-DRAFT"
    ledger["next_gate"] = "S2-C 完成；下一步进行 E01–E36 逐集正式剧本、表演、分镜与 AIGC 资产绑定前的 Episode Gate。"
    LEDGER_PATH.write_text(json.dumps(ledger, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    hooks = {
        "schema_version": 1,
        "status": "SEASON-DRAFT",
        "scope": "P2 S2-C 648 short chapter hook map",
        "episode_count": 36,
        "chapters_per_episode": 18,
        "chapter_total": 648,
        "duration_seconds_target": [120, 180],
        "entries": build_hook_rows(ledger, parse_draft_rows()),
        "next_gate": "Episode Gate 前不绑定最终对白、shot ID、U 唯一身份或 BG 微章 ID。",
    }
    HOOK_PATH.write_text(json.dumps(hooks, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"materialized season S2-C ledger={len(ledger['episodes'])} hooks={len(hooks['entries'])}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
